function showPerkTooltip(icon){if(!icon)return;const card=icon.querySelector('.perk-hover-card');if(!card)return;activePerkIcon=icon;const title=card.querySelector('b')?.textContent||'Perk',rank=card.querySelector('em')?.textContent||'',desc=card.querySelector('span')?.textContent||'';perkGlobalTooltip.querySelector('b').textContent=title;perkGlobalTooltip.querySelector('em').textContent=rank;perkGlobalTooltip.querySelector('span').textContent=desc;const color=getComputedStyle(icon).getPropertyValue('--perk-color').trim()||'#ffe38a';perkGlobalTooltip.style.setProperty('--perk-color',color);perkGlobalTooltip.classList.add('visible');const r=icon.getBoundingClientRect(),w=Math.min(220,window.innerWidth-20),inBuildMenu=!!icon.closest('.build-modal,.pause-build-panel');let left;left=Math.max(10,Math.min(window.innerWidth-w-10,r.left+r.width/2-w/2));perkGlobalTooltip.style.left=left+'px';const h=perkGlobalTooltip.getBoundingClientRect().height;let top=r.top-h-9;if(top<8)top=Math.min(window.innerHeight-h-8,r.bottom+9);top=Math.max(8,Math.min(window.innerHeight-h-8,top));perkGlobalTooltip.style.top=top+'px'}

