function showCoreGlobalTip(el){if(!el||!el.matches('.core-ability-icon,.core-evo-icon,.core-exclusive-icons>span'))return;const title=el.dataset.tipTitle||el.querySelector('.core-hover-tip b')?.textContent||el.getAttribute('title')||el.querySelector('small')?.textContent||'Details';const desc=el.dataset.tipDesc||el.querySelector('.core-hover-tip p')?.textContent||el.getAttribute('title')||el.getAttribute('aria-label')||'';if(!desc)return;activeCoreTip=el;coreGlobalTooltip.querySelector('b').textContent=title;coreGlobalTooltip.querySelector('p').textContent=desc;coreGlobalTooltip.classList.add('visible');const r=el.getBoundingClientRect(),w=Math.min(300,window.innerWidth-20);let left=Math.max(10,Math.min(window.innerWidth-w-10,r.left+r.width/2-w/2));coreGlobalTooltip.style.left=left+'px';const h=coreGlobalTooltip.getBoundingClientRect().height;let top=r.top-h-9;if(top<8)top=Math.min(window.innerHeight-h-8,r.bottom+9);coreGlobalTooltip.style.top=Math.max(8,top)+'px'}

